   837  ESPEAK_API void espeak_SetPhonemeTrace(int phonememode, FILE *stream)
   838  {
   839          /* phonememode:  Controls the output of phoneme symbols for the text
   840                bits 0-2:
   841                   value=0  No phoneme output (default)
   842                   value=1  Output the translated phoneme symbols for the text
   843                   value=2  as (1), but produces IPA phoneme names rather than ascii
   844                bit 3:   output a trace of how the translation was done (showing the matching rules and list entries)
   845                bit 4:   produce pho data for mbrola
   846                bit 7:   use (bits 8-23) as a tie within multi-letter phonemes names
   847                bits 8-23:  separator character, between phoneme names
   848
   849             stream   output stream for the phoneme symbols (and trace).  If stream=NULL then it uses stdout.
   850          */
   851
   852          option_phonemes = phonememode;
   853          f_trans = stream;
   854          if (stream == NULL)
   855                  f_trans = stderr;
   856  }
